parameters.text:
Eres un extractor de datos para FrontierAdvice Chile.

Usa la herramienta MCP Playwright para abrir https://x.com/UPFronterizos y leer los últimos 8 posts visibles sin iniciar sesión.

Debes devolver exclusivamente JSON válido con esta estructura:

{
  "items": [
    {
      "codigo_fuente": "los-libertadores",
      "nombre_detectado": "Paso Los Libertadores",
      "estado_general": "cerrado",
      "mensaje_original": "texto del post",
      "fecha_reporte": "2026-05-29T00:00:00Z",
      "confianza_extraccion": 0.92,
      "restricciones": [
        {
          "tipo_restriccion": "clima_nieve",
          "descripcion": "Cierre por nevadas"
        }
      ],
      "alertas": [
        {
          "tipo_alerta": "evento_climatico",
          "descripcion": "Nevadas en alta montaña",
          "fuente": "x_upfronterizos"
        }
      ]
    }
  ]
}

Reglas:
- Ignora posts que no hablen del estado de pasos fronterizos.
- No inventes datos.
- estado_general solo puede ser: habilitado, cerrado, habilitado_con_precaucion, demora, sin_informacion.
- codigo_fuente debe ir en kebab-case.
- Si no logras detectar fecha exacta, usa la fecha actual de ejecución.
- Devuelve solo JSON, sin markdown ni texto adicional.

parameters.jsCode:
const raw = $json.output || $json.text || $json.response || $json.data || $json;
let parsed = raw;

if (typeof raw === 'string') {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
}

if (!parsed.items || !Array.isArray(parsed.items)) {
  throw new Error('El agente no devolvió items[]. Output recibido: ' + JSON.stringify(raw).substring(0, 500));
}

return parsed.items.map(item => ({
  json: {
    codigo_fuente: item.codigo_fuente || null,
    nombre_detectado: item.nombre_detectado || null,
    estado_general: item.estado_general || 'sin_informacion',
    mensaje_original: item.mensaje_original || '',
    fecha_reporte: item.fecha_reporte || new Date().toISOString(),
    confianza_extraccion: item.confianza_extraccion ?? 0.5,
    fuente: 'x_upfronterizos',
    restricciones: Array.isArray(item.restricciones) ? item.restricciones : [],
    alertas: Array.isArray(item.alertas) ? item.alertas : [],
  }
}));;
